datasource db {
  provider = "postgresql"
  // Wasp requires that the url is set to the DATABASE_URL environment variable.
  url      = env("DATABASE_URL")
}

// Wasp requires the `prisma-client-js` generator to be present.
generator client {
  provider = "prisma-client-js"
}

model Product {
  id         String      @id @default(uuid())
  name       String
  price      Float
  inventory  Int
  orderItems OrderItem[]
}

model Coupon {
  id    String @id @default(uuid())
  code  String @unique
  // "PERCENTAGE" | "FLAT"
  type  String
  value Float
}

model Order {
  id         String      @id @default(uuid())
  createdAt  DateTime    @default(now())
  subtotal   Float
  discount   Float
  total      Float
  couponCode String?
  items      OrderItem[]
}

model OrderItem {
  id        String  @id @default(uuid())
  orderId   String
  order     Order   @relation(fields: [orderId], references: [id])
  productId String
  product   Product @relation(fields: [productId], references: [id])
  quantity  Int
  unitPrice Float
}

import { action, app, page, query, route } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { getProducts } from "./src/queries" with { type: "ref" };
import { applyCoupon, checkout } from "./src/actions" with { type: "ref" };
import { devSeed } from "./src/dbSeeds" with { type: "ref" };

export default app({
  name: "app",
  title: "app",
  wasp: { version: "^0.24.0" },
  head: ["<link rel='icon' href='/favicon.ico' />"],
  db: {
    seeds: [devSeed],
  },
  spec: [
    route("RootRoute", "/", page(MainPage)),

    query(getProducts, { entities: ["Product"] }),

    action(applyCoupon, { entities: ["Product", "Coupon"] }),
    action(checkout, { entities: ["Product", "Coupon", "Order", "OrderItem"] }),
  ],
});

export type CouponLike = {
  type: string;
  value: number;
};

/**
 * Computes the discount amount for a given coupon and cart subtotal.
 *
 * - "PERCENTAGE" coupons discount a percentage of the subtotal.
 * - "FLAT" coupons discount a flat amount, capped at the subtotal so the
 *   resulting total never goes below $0.00.
 */
export function computeDiscount(coupon: CouponLike, subtotal: number): number {
  if (coupon.type === "PERCENTAGE") {
    return roundCents((subtotal * coupon.value) / 100);
  }
  if (coupon.type === "FLAT") {
    return roundCents(Math.min(coupon.value, subtotal));
  }
  return 0;
}

export function roundCents(amount: number): number {
  return Math.round(amount * 100) / 100;
}

import type { DbSeedFn } from "wasp/server";

export const devSeed: DbSeedFn = async (prisma) => {
  await prisma.product.createMany({
    data: [
      {
        name: "Premium Wireless Headphones",
        price: 100.0,
        inventory: 10,
      },
      {
        name: "Ergonomic Mechanical Keyboard",
        price: 150.0,
        inventory: 1,
      },
    ],
  });

  await prisma.coupon.createMany({
    data: [
      {
        code: "SAVE20",
        type: "PERCENTAGE",
        value: 20,
      },
      {
        code: "FLAT50",
        type: "FLAT",
        value: 50.0,
      },
    ],
  });
};

import { type GetProducts } from "wasp/server/operations";
import { type Product } from "wasp/entities";

export const getProducts: GetProducts<void, Product[]> = async (
  _args,
  context,
) => {
  return context.entities.Product.findMany({
    orderBy: { name: "asc" },
  });
};

import { type ApplyCoupon, type Checkout } from "wasp/server/operations";
import { HttpError, prisma } from "wasp/server";
import { computeDiscount, roundCents } from "./couponUtils";

export type CartItemInput = {
  productId: string;
  quantity: number;
};

function normalizeCode(code: string): string {
  return code.trim().toUpperCase();
}

/**
 * Merges duplicate cart line items (same productId) into a single entry and
 * drops any non-positive quantities.
 */
function mergeCartItems(items: CartItemInput[]): CartItemInput[] {
  const merged = new Map<string, number>();
  for (const item of items ?? []) {
    if (!item || !item.productId || !Number.isFinite(item.quantity)) {
      continue;
    }
    const quantity = Math.floor(item.quantity);
    if (quantity <= 0) {
      continue;
    }
    merged.set(item.productId, (merged.get(item.productId) ?? 0) + quantity);
  }
  return Array.from(merged.entries()).map(([productId, quantity]) => ({
    productId,
    quantity,
  }));
}

// ---------------------------------------------------------------------------
// applyCoupon
// ---------------------------------------------------------------------------

type ApplyCouponInput = {
  code: string;
  items: CartItemInput[];
};

type ApplyCouponOutput = {
  code: string;
  type: string;
  value: number;
  subtotal: number;
  discount: number;
  total: number;
  message: string;
};

export const applyCoupon: ApplyCoupon<
  ApplyCouponInput,
  ApplyCouponOutput
> = async (args, context) => {
  const items = mergeCartItems(args.items);
  if (items.length === 0) {
    throw new HttpError(400, "Your cart is empty. Add items before applying a coupon.");
  }

  const code = normalizeCode(args.code ?? "");
  if (!code) {
    throw new HttpError(400, "Please enter a coupon code.");
  }

  const coupon = await context.entities.Coupon.findUnique({
    where: { code },
  });
  if (!coupon) {
    throw new HttpError(404, "Invalid coupon code.");
  }

  const productIds = items.map((item) => item.productId);
  const products = await context.entities.Product.findMany({
    where: { id: { in: productIds } },
  });

  let subtotal = 0;
  for (const item of items) {
    const product = products.find((p) => p.id === item.productId);
    if (!product) {
      throw new HttpError(400, "One of the items in your cart no longer exists.");
    }
    subtotal += product.price * item.quantity;
  }
  subtotal = roundCents(subtotal);

  const discount = computeDiscount(coupon, subtotal);
  const total = roundCents(Math.max(0, subtotal - discount));

  return {
    code: coupon.code,
    type: coupon.type,
    value: coupon.value,
    subtotal,
    discount,
    total,
    message: `Coupon "${coupon.code}" applied successfully!`,
  };
};

// ---------------------------------------------------------------------------
// checkout
// ---------------------------------------------------------------------------

type CheckoutInput = {
  items: CartItemInput[];
  couponCode?: string;
};

type CheckoutOutput = {
  orderId: string;
  subtotal: number;
  discount: number;
  total: number;
};

type LockedProductRow = {
  id: string;
  name: string;
  price: number;
  inventory: number;
};

export const checkout: Checkout<CheckoutInput, CheckoutOutput> = async (
  args,
) => {
  const items = mergeCartItems(args.items);
  if (items.length === 0) {
    throw new HttpError(400, "Your cart is empty. Add items before checking out.");
  }

  // Lock product rows in a stable order (sorted by id) to avoid deadlocks
  // between concurrent checkout transactions that touch overlapping sets of
  // products.
  const sortedProductIds = [...items.map((i) => i.productId)].sort();

  const order = await prisma.$transaction(async (tx) => {
    const lockedProducts: LockedProductRow[] = [];
    for (const productId of sortedProductIds) {
      // `SELECT ... FOR UPDATE` takes a row-level lock that is held for the
      // duration of the transaction. Any other concurrent transaction trying
      // to lock the same row will block until this transaction commits or
      // rolls back, which is what makes the inventory check below safe under
      // concurrency.
      const rows = await tx.$queryRaw<LockedProductRow[]>`
        SELECT "id", "name", "price", "inventory"
        FROM "Product"
        WHERE "id" = ${productId}
        FOR UPDATE
      `;
      const row = rows[0];
      if (!row) {
        throw new HttpError(400, "One of the items in your cart no longer exists.");
      }
      lockedProducts.push(row);
    }

    let subtotal = 0;
    for (const item of items) {
      const product = lockedProducts.find((p) => p.id === item.productId)!;
      if (product.inventory < item.quantity) {
        throw new HttpError(
          400,
          `Insufficient inventory for "${product.name}". Out of stock: only ${product.inventory} left.`,
        );
      }
      subtotal += product.price * item.quantity;
    }
    subtotal = roundCents(subtotal);

    let discount = 0;
    let normalizedCouponCode: string | undefined;
    if (args.couponCode && args.couponCode.trim().length > 0) {
      const code = normalizeCode(args.couponCode);
      const coupon = await tx.coupon.findUnique({ where: { code } });
      if (!coupon) {
        throw new HttpError(404, "Invalid coupon code.");
      }
      discount = computeDiscount(coupon, subtotal);
      normalizedCouponCode = coupon.code;
    }

    const total = roundCents(Math.max(0, subtotal - discount));

    // Decrement inventory for every product in the cart. Because we hold a
    // row lock (from the `FOR UPDATE` select above) for each product involved,
    // this decrement is safe from lost updates / race conditions.
    for (const item of items) {
      await tx.product.update({
        where: { id: item.productId },
        data: { inventory: { decrement: item.quantity } },
      });
    }

    const createdOrder = await tx.order.create({
      data: {
        subtotal,
        discount,
        total,
        couponCode: normalizedCouponCode,
        items: {
          create: items.map((item) => {
            const product = lockedProducts.find(
              (p) => p.id === item.productId,
            )!;
            return {
              productId: item.productId,
              quantity: item.quantity,
              unitPrice: product.price,
            };
          }),
        },
      },
    });

    return createdOrder;
  });

  return {
    orderId: order.id,
    subtotal: order.subtotal,
    discount: order.discount,
    total: order.total,
  };
};

import { useMemo, useState } from "react";
import { useQuery, getProducts, applyCoupon, checkout } from "wasp/client/operations";
import { type Product } from "wasp/entities";
import "./Main.css";

type CartItem = {
  productId: string;
  name: string;
  price: number;
  quantity: number;
};

type AppliedCoupon = {
  code: string;
  type: string;
  value: number;
};

type Feedback = {
  kind: "success" | "error";
  text: string;
};

function computeDiscountLocally(coupon: AppliedCoupon, subtotal: number): number {
  if (coupon.type === "PERCENTAGE") {
    return round2((subtotal * coupon.value) / 100);
  }
  if (coupon.type === "FLAT") {
    return round2(Math.min(coupon.value, subtotal));
  }
  return 0;
}

function round2(amount: number): number {
  return Math.round(amount * 100) / 100;
}

function formatMoney(amount: number): string {
  return `$${amount.toFixed(2)}`;
}

export function MainPage() {
  const {
    data: products,
    isLoading: productsLoading,
    error: productsError,
  } = useQuery(getProducts);

  const [cart, setCart] = useState<CartItem[]>([]);
  const [couponInput, setCouponInput] = useState("");
  const [appliedCoupon, setAppliedCoupon] = useState<AppliedCoupon | null>(null);
  const [couponFeedback, setCouponFeedback] = useState<Feedback | null>(null);
  const [checkoutFeedback, setCheckoutFeedback] = useState<Feedback | null>(null);
  const [isApplyingCoupon, setIsApplyingCoupon] = useState(false);
  const [isCheckingOut, setIsCheckingOut] = useState(false);

  const subtotal = useMemo(
    () => round2(cart.reduce((sum, item) => sum + item.price * item.quantity, 0)),
    [cart],
  );

  const discount = useMemo(() => {
    if (!appliedCoupon) return 0;
    return computeDiscountLocally(appliedCoupon, subtotal);
  }, [appliedCoupon, subtotal]);

  const total = round2(Math.max(0, subtotal - discount));

  function addToCart(product: Product) {
    setCheckoutFeedback(null);
    setCart((prev) => {
      const existing = prev.find((item) => item.productId === product.id);
      if (existing) {
        return prev.map((item) =>
          item.productId === product.id
            ? { ...item, quantity: item.quantity + 1 }
            : item,
        );
      }
      return [
        ...prev,
        {
          productId: product.id,
          name: product.name,
          price: product.price,
          quantity: 1,
        },
      ];
    });
  }

  function removeFromCart(productId: string) {
    setCart((prev) => prev.filter((item) => item.productId !== productId));
  }

  async function handleApplyCoupon() {
    setCouponFeedback(null);
    if (cart.length === 0) {
      setCouponFeedback({ kind: "error", text: "Your cart is empty. Add items before applying a coupon." });
      return;
    }
    if (!couponInput.trim()) {
      setCouponFeedback({ kind: "error", text: "Please enter a coupon code." });
      return;
    }

    setIsApplyingCoupon(true);
    try {
      const result = await applyCoupon({
        code: couponInput,
        items: cart.map((item) => ({ productId: item.productId, quantity: item.quantity })),
      });
      setAppliedCoupon({ code: result.code, type: result.type, value: result.value });
      setCouponFeedback({ kind: "success", text: result.message });
    } catch (err: any) {
      setAppliedCoupon(null);
      setCouponFeedback({
        kind: "error",
        text: err?.message ?? "Failed to apply coupon.",
      });
    } finally {
      setIsApplyingCoupon(false);
    }
  }

  async function handleCheckout() {
    setCheckoutFeedback(null);
    if (cart.length === 0) {
      setCheckoutFeedback({ kind: "error", text: "Your cart is empty. Add items before checking out." });
      return;
    }

    setIsCheckingOut(true);
    try {
      const result = await checkout({
        items: cart.map((item) => ({ productId: item.productId, quantity: item.quantity })),
        couponCode: appliedCoupon?.code,
      });
      setCheckoutFeedback({
        kind: "success",
        text: `Order placed successfully! Order ID: ${result.orderId}`,
      });
      setCart([]);
      setAppliedCoupon(null);
      setCouponInput("");
      setCouponFeedback(null);
    } catch (err: any) {
      setCheckoutFeedback({
        kind: "error",
        text: err?.message ?? "Checkout failed. Please try again.",
      });
    } finally {
      setIsCheckingOut(false);
    }
  }

  return (
    <main className="shop-container">
      <h1 className="shop-title">Wasp Shop</h1>

      {productsError && (
        <p className="feedback feedback-error">Failed to load products.</p>
      )}

      <section className="catalog">
        <h2>Products</h2>
        {productsLoading && <p>Loading products...</p>}
        <div className="product-list">
          {products?.map((product) => (
            <div className="product-card" key={product.id} data-testid={`product-${product.id}`}>
              <div className="product-info">
                <span className="product-name">{product.name}</span>
                <span className="product-price">{formatMoney(product.price)}</span>
                <span className="product-inventory">
                  {product.inventory > 0
                    ? `In stock: ${product.inventory}`
                    : "Out of stock"}
                </span>
              </div>
              <button
                className="button button-filled"
                disabled={product.inventory <= 0}
                onClick={() => addToCart(product)}
              >
                Add to Cart
              </button>
            </div>
          ))}
        </div>
      </section>

      <section className="cart">
        <h2>Cart</h2>
        {cart.length === 0 ? (
          <p>Your cart is empty.</p>
        ) : (
          <table className="cart-table">
            <thead>
              <tr>
                <th>Item</th>
                <th>Qty</th>
                <th>Price</th>
                <th>Line Total</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              {cart.map((item) => (
                <tr key={item.productId}>
                  <td>{item.name}</td>
                  <td>{item.quantity}</td>
                  <td>{formatMoney(item.price)}</td>
                  <td>{formatMoney(round2(item.price * item.quantity))}</td>
                  <td>
                    <button
                      className="button button-outlined button-small"
                      onClick={() => removeFromCart(item.productId)}
                    >
                      Remove
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}

        <div className="coupon-row">
          <input
            id="coupon-input"
            type="text"
            placeholder="Enter Coupon Code"
            value={couponInput}
            onChange={(e) => setCouponInput(e.target.value)}
          />
          <button
            id="apply-coupon-btn"
            className="button button-outlined"
            onClick={handleApplyCoupon}
            disabled={isApplyingCoupon}
          >
            Apply Coupon
          </button>
        </div>
        {couponFeedback && (
          <p className={`feedback feedback-${couponFeedback.kind}`}>
            {couponFeedback.text}
          </p>
        )}

        <div className="totals">
          <div className="totals-row">
            <span>Subtotal</span>
            <span>{formatMoney(subtotal)}</span>
          </div>
          <div className="totals-row">
            <span>Discount</span>
            <span>-{formatMoney(discount)}</span>
          </div>
          <div className="totals-row totals-grand">
            <span>Grand Total</span>
            <span>{formatMoney(total)}</span>
          </div>
        </div>

        <button
          id="checkout-btn"
          className="button button-filled checkout-button"
          onClick={handleCheckout}
          disabled={isCheckingOut || cart.length === 0}
        >
          Place Order
        </button>
        {checkoutFeedback && (
          <p className={`feedback feedback-${checkoutFeedback.kind}`}>
            {checkoutFeedback.text}
          </p>
        )}
      </section>
    </main>
  );
}

* {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family:
    -apple-system, BlinkMacSystemFont, "Segoe UI", "Roboto", "Oxygen", "Ubuntu",
    "Cantarell", "Fira Sans", "Droid Sans", "Helvetica Neue", sans-serif;
}

#root {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.button {
  font-size: 1rem;
  font-weight: 700;
  text-decoration: none;
  padding: 0.7rem 1.2rem;
  border-radius: 10px;
  cursor: pointer;
}

.button-small {
  padding: 0.35rem 0.7rem;
  font-size: 0.85rem;
}

.button-filled {
  color: black;
  background-color: #ffcc00;
  border: 2px solid #ffcc00;
  transition: all 0.2s ease-in-out;
}

.button-filled:hover {
  filter: brightness(0.95);
}

.button-filled:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.button-outlined {
  color: black;
  background-color: transparent;
  border: 2px solid #ffcc00;
  transition: all 0.2s ease-in-out;
}

.button-outlined:hover {
  filter: brightness(0.95);
}

.button-outlined:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

code {
  border-radius: 5px;
  border: 1px solid #ffcc00;
  padding: 0.2rem;
  background: #ffcc0044;
  font-family:
    Menlo,
    Monaco,
    Lucida Console,
    Liberation Mono,
    DejaVu Sans Mono,
    Bitstream Vera Sans Mono,
    Courier New,
    monospace;
}

/* --- Shop layout --- */

.shop-container {
  width: 100%;
  max-width: 780px;
  margin: 2rem auto 6rem auto;
  padding: 0 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

.shop-title {
  font-size: 2.5rem;
  font-weight: 700;
  text-align: center;
}

.catalog,
.cart {
  border: 1px solid #e0e0e0;
  border-radius: 12px;
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.product-list {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.product-card {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border: 1px solid #eee;
  border-radius: 10px;
  padding: 1rem;
  gap: 1rem;
}

.product-info {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.product-name {
  font-weight: 700;
}

.product-price {
  color: #333;
}

.product-inventory {
  font-size: 0.85rem;
  color: #777;
}

.cart-table {
  width: 100%;
  border-collapse: collapse;
}

.cart-table th,
.cart-table td {
  text-align: left;
  padding: 0.5rem;
  border-bottom: 1px solid #eee;
}

.coupon-row {
  display: flex;
  gap: 0.75rem;
  align-items: center;
}

.coupon-row input {
  flex: 1;
  padding: 0.7rem 1rem;
  border-radius: 10px;
  border: 2px solid #e0e0e0;
  font-size: 1rem;
}

.totals {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  border-top: 1px solid #eee;
  padding-top: 1rem;
}

.totals-row {
  display: flex;
  justify-content: space-between;
}

.totals-grand {
  font-weight: 700;
  font-size: 1.2rem;
}

.checkout-button {
  width: 100%;
}

.feedback {
  padding: 0.6rem 1rem;
  border-radius: 8px;
  font-size: 0.95rem;
}

.feedback-success {
  background-color: #d7f7de;
  color: #175c2c;
}

.feedback-error {
  background-color: #fbdada;
  color: #7a1414;
}

